// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        // deployer (admin) is this test contract; keep actor distinct from it so
        // the delegated owner is NOT the admin, and force a real change of owner.
        vm.assume(actor != address(this));
        vm.assume(newOwner != actor);

        // Admin hands ownership to the fuzzed actor.
        vm.prank(address(this));
        c.setOwner(actor);

        // Rule: a non-admin caller (even the current owner) must fail to change owner.
        vm.prank(actor);
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok && c.owner() == actor);
    }
}
